contract InvMutTest {
    C public c;
    constructor(C _c) { c = _c; }

    // Drive minimal sequence: set storage so that _RState_ == BELOW_ONE and BASE_RESERVE_ <-> BASE_TARGET_ relation can be observed.
    // We rely only on public surface: getters getVaultReserve() and getPMMStateForCall().
    function check(address maintainer, uint256 baseReserve, uint256 quoteReserve, uint256 baseTarget, uint256 quoteTarget, uint256 i, uint256 k) public {
        // Preconditions: caller is maintainer for actions that might be needed off-chain (we don't call onlyMaintainer funcs here).
        // We will simulate the state by calling buyShares/sellShares which change reserves/targets through public functions.
        // To keep it simple and minimal, assume contract already in desired state; verifier will place c with various states.

        // Read current PMM state and reserves
        (uint256 si, uint256 sk, uint256 sB, uint256 sQ, uint256 sB0, uint256 sQ0, uint256 sR) = c.getPMMStateForCall();
        (uint256 vaultBase, uint256 vaultQuote) = c.getVaultReserve();

        // We only proceed when the pool is in BELOW_ONE state (precondition). If not, we do nothing but still assert vacuously.
        // Ensure we're checking the meaningful case by requiring R == BELOW_ONE.
        require(sR == uint256(uint32(PMMPricing.RState.BELOW_ONE)), "PRE: not BELOW_ONE");

        // Call the deciding function
        c.correctRState();

        // Read targets and reserves after potential correction
        (si, sk, sB, sQ, sB0, sQ0, sR) = c.getPMMStateForCall();
        (vaultBase, vaultQuote) = c.getVaultReserve();

        // The invariant for the original contract P: when coming from BELOW_ONE, after correction BASE_TARGET equals BASE_RESERVE or is <= BASE_RESERVE.
        // We assert BASE_TARGET <= BASE_RESERVE (observable as sB0 <= vaultBase).
        assert(sB0 <= vaultBase);
    }

    // Allow receiving Ether if needed by underlying token interactions
    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 baseDeposit, uint256 quoteDeposit) public payable {
        // Precondition: ensure non-empty pool initialization path and valid deposits
        require(baseDeposit > 0, "need baseDeposit>0");
        // read initial relevant public values
        (uint256 i, uint256 K, uint256 B, uint256 Q, uint256 B0_before, uint256 Q0_before, uint256 R_before) = c.getPMMStateForCall();
        // ensure RState is BELOW_ONE so the mutated branch is relevant
        require(R_before == uint256(uint32(2)) || R_before == uint256(0) || R_before == uint256(1) || true);
        // Deposit by transferring tokens into the contract is not possible here; we instead call buyShares which expects the contract to already hold tokens.
        // Use buyShares call (it will compute baseInput and update targets based on balances inside c). The test provides arbitrary args for to.
        address to = address(this);
        // Call buyShares; it will mutate BASE_TARGET possibly differently in mutant
        c.buyShares(to);
        // Read post-state BASE_TARGET and reserves via getPMMStateForCall
        ( , , uint256 B_after, , uint256 B0_after, , uint256 R_after) = c.getPMMStateForCall();
        // The general rule: when R was BELOW_ONE before the call, BASE_TARGET after the call should be <= max(previous BASE_TARGET, current BASE_RESERVE)
        // We express it using observable B0_before, B0_after, and B_after. For original this holds; mutant can make B0_after exceed B_after when it wrongly updates based on > instead of <.
        // Determine whether we consider the BEFORE RState was BELOW_ONE by reading initial R_before via getPMMStateForCall above.
        bool wasBelowOne = (R_before == uint256(uint32(0)));
        assert(!wasBelowOne || B0_after <= B_after);
    }
    receive() external payable {}
}

