contract InvMutTest {
    C public c;
    constructor(C _c) { c = _c; }

    // Drive minimal sequence: set up state so that _RState_ == ABOVE_ONE and _QUOTE_RESERVE_ < _QUOTE_TARGET_
    // We can't access internals directly; use public functions to manipulate reserves via buyShares/sellShares and transfers.
    // The test takes parameters to allow the verifier to explore values.
    function run(address baseTokenHolder, address quoteTokenHolder, uint256 baseDeposit, uint256 quoteDeposit) public {
        // Preconditions for meaningful operations
        require(baseDeposit > 0 && quoteDeposit > 0);

        // We assume provided token holders have approved and funded c before; we only call public functions.
        // Call buyShares to initialize pool if needed (totalSupply==0 path) by simulating token transfers into c.
        // We cannot transfer tokens here, so require pool already initialized by environment; otherwise getMidPrice and reserves remain unchanged.

        // Read current PMM state via public getter
        (uint256 i, uint256 K, uint256 B, uint256 Q, uint256 B0, uint256 Q0, uint256 R) = c.getPMMStateForCall();

        // We require starting R to be ABOVE_ONE and quote reserve strictly less than quote target
        require(R == uint256(2)); // PMMPricing.RState.ABOVE_ONE == 2
        require(Q < Q0);

        // Call correctRState which on P should NOT change RState in this scenario (only when QUOTE_RESERVE_ < QUOTE_TARGET_ does it reset for ABOVE_ONE, but original P checks QUOTE_RESERVE_ < QUOTE_TARGET_ to reset — here Q < Q0 so P would reset; wait - adjust: We must target the change: mutant uses > instead of < so behavior differs when Q < Q0.
        // We want a property that holds on P and violated by M. On original P, for ABOVE_ONE it resets when QUOTE_RESERVE_ < QUOTE_TARGET_ (so with Q<Q0 it WOULD reset). Mutant resets when Q>Q0, so with Q<Q0 mutant would NOT reset. So pick property: after call, RState == ONE. That holds on P but breaks on M.

        c.correctRState();

        (,,,,,, uint256 R_after) = c.getPMMStateForCall();

        // Assert that RState became ONE (0) — holds on original, violated by mutant which wouldn't reset here
        assert(R_after == uint256(0));
    }

    // allow receiving ETH if needed by environment
    receive() external payable {}
    fallback() external payable {}
}

