        (,,uint256 B, uint256 Q, uint256 B0, uint256 Q0, uint256 R) = c.getPMMStateForCall();
        require(R == uint256(uint32(1)), "pre: not ABOVE_ONE"); // PMMPricing.RState.ABOVE_ONE == 1
        require(Q <= Q0, "pre: quote reserve already above target");

